:root {
  --color-primary: #2c2c2c;
  --color-secondary: #f5f5f5;
  --color-accent: #b8956a;
  --color-text: #333;
  --color-text-light: #666;
  --color-border: #e0e0e0;
  --color-white: #fff;
  --color-error: #c94444;
  --color-success: #5a7e47;

  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;

  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
  --font-size-base: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 3rem;

  --line-height-tight: 1.2;
  --line-height-normal: 1.5;

  --transition-speed: 300ms;
  --border-radius: 4px;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Base Styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  color: var(--color-text);
  background-color: var(--color-white);
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-sm);
  z-index: 100;
  text-decoration: none;
  border-radius: 0 0 var(--border-radius) 0;
  font-weight: 600;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

/* Utility Classes */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Header & Navigation */
.site-header {
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 50;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-md);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-lg);
}

.logo h1 {
  font-size: var(--font-size-xl);
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--color-primary);
}

.main-nav {
  flex: 1;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-xs);
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
}

.nav-toggle:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.nav-toggle-icon {
  display: inline-block;
  width: 24px;
  height: 24px;
  margin-right: var(--spacing-xs);
  vertical-align: middle;
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-lg);
}

.nav-menu a {
  color: var(--color-text);
