.main-nav {
  flex: 1;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-xs);
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
}

.nav-toggle:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.nav-toggle-icon {
  display: inline-block;
  width: 24px;
  height: 24px;
  margin-right: var(--spacing-xs);
  vertical-align: middle;
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-lg);
}

.nav-menu a {
  color: var(--color-text);
  text-decoration: none;
  font-weight: 500;
  transition: color var(--transition-speed);
  display: block;
  padding: var(--spacing-sm) 0;
  border-bottom: 2px solid transparent;
}

.nav-menu a:hover,
.nav-menu a:focus {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
  outline: none;
}

.header-actions {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
}

.icon-btn {
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  padding: var(--spacing-xs);
  transition: transform var(--transition-speed);
}

.icon-btn:hover {
  transform: scale(1.1);
}

.icon-btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: var(--border-radius);
}

/* Buttons */
.btn {
  display: inline-block;
  padding: var(--spacing-sm) var(--spacing-lg);
  border: none;
  border-radius: var(--border-radius);
  font-size: var(--font-size-base);
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-speed);
  text-decoration: none;
  text-align: center;
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background-color: var(--color-accent);
}

.btn-primary:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-secondary {
  background-color: var(--color-secondary);
  color: var(--color-primary);
  border: 1px solid var(--color-border);
}

.btn-secondary:hover {
  background-color: var(--color-border);
}

.btn-secondary:focus {
  outline: 3px solid var(--color-accent);
